template.script:
document.addEventListener('DOMContentLoaded', function () {
    const appId = '';
    const amount = parseFloat('');
    const memo = '';
    const txRef = '';

    // Inicializar Pi SDK
    try {
        Pi.init({ version: "2.0", sandbox: false }); // Cambiar a true para pruebas
    } catch (e) {
        console.error("Error inicializando Pi SDK", e);
    }

    document.getElementById('btn-pay-pi').addEventListener('click', function() {
        Pi.createPayment({
            amount: amount,
            memo: memo,
            metadata: { reference: txRef },
        }, {
            onReadyForServerApproval: function(paymentId) {
                // Llamar a nuestro controlador Odoo
                fetch('/payment/pi_network/approve', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({ params: { paymentId: paymentId, tx_reference: txRef }})
                });
            },
            onReadyForServerCompletion: function(paymentId, txid) {
                // Llamar a nuestro controlador Odoo tras confirmación blockchain
                fetch('/payment/pi_network/complete', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({ params: { paymentId: paymentId, txid: txid, tx_reference: txRef }})
                }).then(() => {
                    window.location.href = '/payment/status';
                });
            },
            onCancel: function(paymentId) { console.log("Pago cancelado por el usuario."); },
            onError: function(error, payment) { console.error("Error en el pago", error); }
        });
    });
});
